  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const invoice = result.value;
  const updated = removeLine(invoice, 'UNKNOWN-SKU');
  assert.equal(updated.ok, false);
  assert.equal(updated.error, 'LINE_NOT_FOUND');
});

test('removeLine handles NO_LINES when removing the last line', () => {
