test('removeLine handles NOT_DRAFT for non-draft invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  const invoice = { ...result.value, status: 'sent' };
  const updated = removeLine(invoice, 'DEV-HOUR');
  assert.equal(updated.ok, false);
  assert.equal(updated.error, 'NOT_DRAFT');
});

test('removeLine does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  const invoice = result.value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));
  removeLine(invoice, 'DEV-HOUR');
  assert.deepEqual(invoice, invoiceCopy);
});
